import { createSlice, createSelector } from '@reduxjs/toolkit';

const initialState = {
  items: [
    {
      id: 1,
      name: "Gaming Laptop",
      price: 1299.99,
      description: "High-performance gaming laptop with RTX 3080",
      image: "https://images.unsplash.com/photo-1603302576837-37561b2e2302?w=500",
      featured: true,
      category: "electronics"
    },
    {
      id: 2,
      name: "Wireless Headphones",
      price: 199.99,
      description: "Premium noise-canceling headphones",
      image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=500",
      featured: true,
      category: "accessories"
    },
    {
      id: 3,
      name: "Smart Watch",
      price: 299.99,
      description: "Feature-rich smartwatch with health tracking",
      image: "https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=500",
      featured: true,
      category: "electronics"
    },
    {
      id: 4,
      name: "4K Monitor",
      price: 499.99,
      description: "32-inch 4K HDR Monitor",
      image: "https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=500",
      featured: false,
      category: "electronics"
    },
    {
      id: 5,
      name: "Mechanical Keyboard",
      price: 149.99,
      description: "RGB Mechanical Gaming Keyboard",
      image: "https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?w=500",
      featured: false,
      category: "accessories"
    },
    {
      id: 6,
      name: "Wireless Mouse",
      price: 79.99,
      description: "Ergonomic Wireless Gaming Mouse",
      image: "https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=500",
      featured: false,
      category: "accessories"
    }
  ],
  filters: {
    search: '',
    priceRange: [0, 1500],
    category: 'all'
  }
};

const productsSlice = createSlice({
  name: 'products',
  initialState,
  // Add these reducers to your existing productsSlice
  reducers: {
    addProduct: (state, action) => {
      state.items.push(action.payload);
    },
    updateProduct: (state, action) => {
      const index = state.items.findIndex(item => item.id === action.payload.id);
      if (index !== -1) {
        state.items[index] = action.payload;
      }
    },
    deleteProduct: (state, action) => {
      state.items = state.items.filter(item => item.id !== action.payload);
    },
    setFilters: (state, action) => {
      state.filters = { ...state.filters, ...action.payload };
    }
  }
});

export const selectProducts = state => state.products;
export const selectFilters = state => state.products.filters;

export const selectFilteredProducts = createSelector(
  [selectProducts, selectFilters],
  (products, filters) => {
    return products.items.filter(product => {
      const matchesSearch = product.name.toLowerCase().includes(filters.search.toLowerCase());
      const matchesPrice = product.price >= filters.priceRange[0] && product.price <= filters.priceRange[1];
      const matchesCategory = filters.category === 'all' || product.category === filters.category;
      return matchesSearch && matchesPrice && matchesCategory;
    });
  }
);

export const selectFeaturedProducts = createSelector(
  [selectProducts],
  (products) => products.items.filter(product => product.featured)
);

export const { setFilters } = productsSlice.actions;
export default productsSlice.reducer;
